def move_profile_resume_to_private_storage(apps, schema_editor):
    """Profile.resume_pdf lived in public /media/; resumes are now private and
    email-gated. Move any existing file into a Resume and delete the public
    copy, so it can't keep being downloaded without the gate."""
    from django.core.files.base import ContentFile

    Profile = apps.get_model("portfolio", "Profile")
    Resume = apps.get_model("portfolio", "Resume")
    profile = Profile.objects.filter(pk=1).first()
    if not profile or not profile.resume_pdf:
        return
    public_file = profile.resume_pdf
    try:
        with public_file.open("rb") as fh:
            content = fh.read()
    except FileNotFoundError:
        return
    resume = Resume(label="Resume (moved from profile)", is_active=True)
    resume.file.save("resume.pdf", ContentFile(content), save=False)
    resume.save()
    public_file.storage.delete(public_file.name)


